<template><div class="page ops-home"><div class="intro"><div><span class="eyebrow">TK CROSS-BORDER OPERATIONS</span><h1>今日运营总览</h1><p>从今天的待办、广告提醒和内容交付开始工作。</p></div><el-button type="primary" @click="router.push('/workbench/today')">打开今日工作台</el-button></div><div class="ops-stat-grid"><div v-for="item in stats" :key="item.key" class="ops-stat"><span>{{ item.label }}</span><strong>{{ item.value }}</strong><small>{{ item.hint }}</small></div></div><div class="ops-grid"><section class="workspace-panel"><div class="section-head"><h3>需要关注</h3><el-link @click="router.push('/ads')">广告计划中心</el-link></div><div v-for="item in workbench.ad_alerts" :key="item.id" class="alert-row"><strong>{{ item.plan_name }}</strong><span>{{ item.current_status }}</span></div><el-empty v-if="!workbench.ad_alerts?.length" description="暂无广告异常" :image-size="50"/></section><section class="workspace-panel"><div class="section-head"><h3>内容交付</h3><el-link @click="router.push('/content/dashboard')">内容生产中心</el-link></div><div class="home-link-row"><span>待完成混剪方案</span><strong>{{ workbench.content_projects?.length || 0 }}</strong></div><div class="home-link-row"><span>待上传成片</span><strong>{{ workbench.pending_videos?.length || 0 }}</strong></div><el-button type="primary" plain @click="router.push('/assistant')">创建内容方案</el-button></section></div><section class="workspace-panel"><div class="section-head"><h3>最近运营记录</h3><el-link @click="router.push('/operations')">查看全部</el-link></div><div v-for="item in workbench.recent_operations" :key="item.id" class="home-link-row"><span>{{ operationLabel(item.operation_type) }} · {{ item.reason || '未填写原因' }}</span><small>{{ item.operated_at }}</small></div><el-empty v-if="!workbench.recent_operations?.length" description="暂无运营记录" :image-size="50"/></section></div></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import axios from 'axios'; const router=useRouter(); const workbench=ref<any>({}); const stats=ref<any[]>([]); const operationLabel=(value:string)=>value==='direct_stop'?'直接关停':'重建并修改目标 ROI'; onMounted(async()=>{const [w,d]=await Promise.all([axios.get('/api/workbench/today'),axios.get('/api/dashboard')]);workbench.value=w.data;stats.value=[{key:'tasks',label:'今日待办',value:w.data.tasks?.length||0,hint:'按运营 SOP 检查'},{key:'ads',label:'广告提醒',value:w.data.ad_alerts?.length||0,hint:'需要回 TikTok 确认'},{key:'content',label:'待完成方案',value:w.data.content_projects?.length||0,hint:'内容生产中心'},{key:'videos',label:'待上传成片',value:w.data.pending_videos?.length||0,hint:'上传剪映导出文件'},{key:'assets',label:'内容资产',value:d.data.assets||0,hint:'可检索和复用'}]});</script>
